function refreshUnknowns() { const p = S.project; const pendingEdge = p.brief.functions.some(f => f.where === I.EDGE_UNSET && !f.alternative); p.brief.unknowns = p.brief.unknowns.filter(u => !(/^which edge to screen|was read as (north|south) \(plan up\)/.test(u) && !pendingEdge && /^which edge/.test(u)) && !(/dimension|scale/.test(u) && p.site.scale.status !== 'unknown') && !(/^light$/.test(u) && p.site.conditions.light.value) && !(/^soil/.test(u) && p.site.conditions.soil_type.value && p.site.conditions.soil_drainage.value)); }
