  for (const c of pv.changes) { const b = M.setBedGeometry(p, c.bed_id, c.after.polygon, c.after.holes, 'user-edited', `said: "${S.bedCmd?.utterance || ''}" — ${c.why}`); if (b) { b.min_width_m = c.after.min_width_m; b.under_canopy = []; } }
  for (const r of pv.removed) { const b = p.site.beds.find(x => x.id === r.bed_id); if (b) { b.status = 'rejected'; b.confirmation = 'rejected'; } }
  for (const a of pv.added) { const id = M.addBed(p, a.polygon, 'user-accepted', a.name, `said: "${S.bedCmd?.utterance || ''}"`, a); S.bedId = id; }
  if (pv.open_area) { const f = p.site.features.find(x => x.id === pv.open_area.id); if (f) { f.polygon = pv.open_area.after.polygon.map(G.roundPt); f.status = 'user-edited'; f.source = `said: "${S.bedCmd?.utterance || ''}"`; } }
