    if (ev.code === 'Space' && S.stage !== 'welcome') { space = true; ev.preventDefault(); }
    if ((ev.key === 'f' || ev.key === 'F') && (S.stage === 'site' || S.stage === 'intent') && !ev.metaKey && !ev.ctrlKey) { S.pz = { x: 0, y: 0, k: 1 }; renderCanvas(); }
