  $('#say0').addEventListener('keydown', ev => { if (ev.key === 'Enter' && (ev.metaKey || ev.ctrlKey)) { ev.preventDefault(); $('#welcome-form').requestSubmit(); } });
  $('#example').onclick = () => { $('#say0').value = EXAMPLE; $('#say0').focus(); };
  $('#newproj').onclick = newProject;
  $('#to-intent').onclick = () => { if (beds().some(b => b.status === 'ai-suggested')) acceptLayout(); unlock('intent'); setStage('intent'); update(); };   /* Confirm model: the suggested beds become the beds, as drawn */
  $('#generate').onclick = () => generate();
  $('#open-garden').onclick = () => setStage('garden'); $('#regen-gate').onclick = () => generate(); $('#gate-thumb').onclick = () => setStage('garden');
  $('#imgfile').addEventListener('change', ev => { const f = ev.target.files[0]; if (!f) return; const rd = new FileReader(); rd.onload = () => { const img = new Image(); img.onload = () => { const B = S.project.site.boundary ? G.bbox(S.project.site.boundary) : { minx: 0, miny: 0, w: 8 }; const w = B.w || 8; S.overlay = { src: rd.result, name: f.name, x: B.minx, y: B.miny, w, h: w * img.height / img.width, opacity: .5, show: true }; M.addInput(S.project, { type: 'image', role: 'visual-reference', name: f.name, geometry_precision: 'unknown', note: 'shown under the plan for tracing; automatic recognition is not implemented — draw beds and features over it, then calibrate a known length' }); M.say(S.project, 'sys', `image "${f.name}" added as a reference overlay (${img.width}×${img.height} px). No automatic interpretation: trace the boundary, beds and features with the tools, then Calibrate two points of known distance.`); if (S.stage !== 'welcome') unlock('site'); S.inspectorOpen = true; update(); }; img.src = rd.result; }; rd.readAsDataURL(f); ev.target.value = ''; });
  addEventListener('scroll', () => $('#top').classList.toggle('scrolled', scrollY > 8), { passive: true });
  document.body.addEventListener('submit', async ev => {
    if (ev.target.id === 'site-form' || ev.target.id === 'intent-form' || ev.target.id === 'gform') { ev.preventDefault(); const ta = ev.target.querySelector('textarea'); const t = ta.value; ta.value = ''; await handleSay(t); if (S.stage === 'garden') { S.composerOpen = !S.preview; renderGarden(); } }
  });
  document.body.addEventListener('keydown', ev => { if (ev.target.tagName === 'TEXTAREA' && ev.target.id !== 'say0' && ev.key === 'Enter' && !ev.shiftKey) { ev.preventDefault(); ev.target.form?.requestSubmit(); } });
  document.body.addEventListener('toggle', ev => { if (ev.target.id === 'inspector') S.inspectorOpen = ev.target.open; }, true);
